-- Migration 0028 — ALL of Phase 5's schema, in ONE generate round.
--
-- GENERATED by drizzle-kit from the schema barrel, then renamed from its random
-- tag (`0028_bizarre_skullbuster`), RE-STAMPED in meta/_journal.json, and
-- hand-extended with the CHECK widening and the GRANT block below. The generated
-- statements themselves were NOT edited — unlike 0025, this generate emitted no
-- drift against `cadences`, because the 0027 snapshot records the full merged
-- schema (see the quick-task note in STATE.md).
--
-- ── WHY ONE MIGRATION FOR THE WHOLE PHASE ───────────────────────────────────
--
-- STATE.md records the drizzle-kit journal-ordering trap firing on three
-- consecutive Phase 2 plans: `generate` stamps an entry with a wall-clock
-- `when` that can land BEHIND the current head, and `migrate` then silently
-- skips it. Every additional generate round in a phase is another roll of that
-- die. So all seven Phase 5 plans' tables and columns are laid here, once, and
-- the later plans add code against a schema that already exists.
--
-- The monotonicity guard in tests/lint-ban.test.ts checks the journal orders;
-- it CANNOT see a journal-vs-database disagreement. Only a second, no-op
-- `db:migrate` proves that, and this migration was verified that way.
--
-- ── WHAT IS HERE ────────────────────────────────────────────────────────────
--
--   message_templates  NEW, config family (cascades) — append-only per-touch
--                      template VERSIONS with write-once approval attestation.
--   touch_drafts       NEW, evidence family (no FKs) — one row per generation
--                      attempt, the AI-04 audit record.
--   cadence_settings   + six nullable voice-profile columns (D-05).
--   inbound_messages   + five classification columns (AI-02).
--   cadences           pause-reason vocabulary gains 'onboarding' (D-07) —
--                      hand-written below, because that CHECK lives in
--                      migration 0017 and not in the drizzle schema.

CREATE TABLE "message_templates" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"touch_number" smallint NOT NULL,
	"channel" text DEFAULT 'sms' NOT NULL,
	"version" smallint NOT NULL,
	"body" text NOT NULL,
	"subject" text,
	"approved_at" timestamp with time zone,
	"approval_note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "message_templates_channel_known" CHECK (channel IN ('sms', 'email'))
);
--> statement-breakpoint
ALTER TABLE "message_templates" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
